// 3. CREATE KIDS SPECIAL SECTION

function createKidsSection() {

    const container = document.getElementById("kidsSectionContainer");

    if (!container) return;

    container.innerHTML = `
        <section class="kids-section section-padding">
            <div class="container kids-grid">

                <div class="kids-content">
                    <span class="eyebrow">LITTLE FOOD LOVERS</span>

                    <h2>
                        Happy Tummies,<br>
                        <span>Happy Smiles!</span>
                    </h2>

                    <p>
                        Special treats for our little guests.
                        Enjoy tasty favourites that make family
                        dining even more memorable.
                    </p>

                    <a href="#contact" class="btn btn-primary">
                        Visit FoodieHub →
                    </a>
                </div>

                <div class="kids-cards">

                    ${kidsItems.map(item => `
                        <article class="kids-card">

                            <img
                                src="${item.image}"
                                alt="${item.alt}"
                                loading="lazy"
                                onerror="this.onerror=null;this.src='images/kids-special.jpg'"
                            >

                            <div class="kids-info">

                                <span class="food-label">
                                    ${item.category}
                                </span>

                                <h3>${item.name}</h3>

                                <p class="kids-description">
                                    ${item.description}
                                </p>

                                <div class="food-bottom">

                                    <span class="food-price">
                                        ₹${item.price}
                                    </span>

                                    <button
                                        class="btn btn-primary kids-order-btn"
                                        type="button"
                                    >
                                        Order Now
                                    </button>

                                </div>

                            </div>
                        </article>
                    `).join("")}

                </div>
            </div>
        </section>
    `;

    // Search and load Kids Food Images

    const kidsImages = container.querySelectorAll(".kids-card img");

    kidsItems.forEach((item, index) => {
        getFoodImage(item.search).then(imageURL => {
            if (imageURL && kidsImages[index]) {
                kidsImages[index].src = imageURL;
            }

        });

    });

    // Kids Order Now Button Events

    container.querySelectorAll(".kids-order-btn").forEach((button, index) => {

        button.addEventListener("click", function () {

            const item = kidsItems[index];

            alert(
                "Thank you for choosing FoodieHub!\n" +
                item.name + " - ₹" + item.price
            );

        });

    });

}


