// 5. DISPLAY CUSTOMER REVIEWS

let currentReviewIndex = 0;

function displayReviews() {

    const reviewsGrid = document.getElementById("reviewsGrid");

    if (!reviewsGrid) return;

    reviewsGrid.innerHTML = "";

    for (let i = 0; i < 3; i++) {

        const reviewIndex =
            (currentReviewIndex + i) % customerReviews.length;

        const review = customerReviews[reviewIndex];

        const card = document.createElement("article");
        card.className = "review-card";

        const stars = document.createElement("div");
        stars.className = "stars";
        stars.textContent = review.rating;

        const message = document.createElement("p");
        message.textContent = `"${review.message}"`;

        const author = document.createElement("div");
        author.className = "review-author";

        const avatar = document.createElement("div");
        avatar.className = "avatar";
        avatar.textContent = review.name.charAt(0).toUpperCase();

        const authorDetails = document.createElement("div");

        const name = document.createElement("h3");
        name.textContent = review.name;

        const role = document.createElement("span");
        role.textContent = review.role;

        authorDetails.append(name, role);
        author.append(avatar, authorDetails);
        card.append(stars, message, author);

        reviewsGrid.appendChild(card);
    }
}


// 6. AUTOMATIC REVIEW SLIDER

function startReviewSlider() {

    displayReviews();

    setInterval(function () {

        currentReviewIndex =
            (currentReviewIndex + 3) % customerReviews.length;

        displayReviews();

    }, 2000);
}


