// 8. FOOD IMAGE SEARCH
// This function is used only for Kids Menu.

async function getFoodImage(searchTerm) {

    const apiURL =
        "https://commons.wikimedia.org/w/api.php" +
        "?action=query" +
        "&generator=search" +
        "&gsrsearch=" + encodeURIComponent(searchTerm) +
        "&gsrnamespace=6" +
        "&gsrlimit=10" +
        "&prop=imageinfo" +
        "&iiprop=url" +
        "&iiurlwidth=600" +
        "&format=json" +
        "&origin=*";

    try {

        const response = await fetch(apiURL);

        if (!response.ok) {
            throw new Error("Image request failed");
        }

        const data = await response.json();
        const pages = data.query?.pages;

        if (!pages) return null;

        const imagePages = Object.values(pages);

        const result = imagePages.find(page => {

            const url = page.imageinfo?.[0]?.thumburl;

            return url && /\.(jpg|jpeg|png|webp)(\?|$)/i.test(url);

        });

        return result?.imageinfo?.[0]?.thumburl || null;

    } catch (error) {

        console.error("Food image error:", error);
        return null;

    }
}


// 9. CREATE FOOD CARD

function createFoodCard(food, index) {

    const card = document.createElement("article");
    card.className = "food-card";

    const imageWrap = document.createElement("div");
    imageWrap.className = "food-image-wrap";

    const image = document.createElement("img");
    image.alt = food.name;
    image.loading = "lazy";

    image.src = food.image ||
        "https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=600&q=80";

    image.onerror = function () {

        this.onerror = null;
        imageWrap.classList.add("image-unavailable");
        this.style.display = "none";

    };

    imageWrap.appendChild(image);

    const content = document.createElement("div");
    content.className = "food-info";

    const category = document.createElement("span");
    category.className = "food-label";
    category.textContent = food.category;

    const heading = document.createElement("h3");
    heading.textContent = food.name;

    const description = document.createElement("p");
    description.textContent = food.description;

    const bottom = document.createElement("div");
    bottom.className = "food-bottom";

    const price = document.createElement("strong");
    price.className = "food-price";
    price.textContent = "₹" + food.price;

    const orderButton = document.createElement("button");
    orderButton.className = "btn btn-primary";
    orderButton.type = "button";
    orderButton.textContent = "Order Now";

    orderButton.addEventListener("click", function () {

        alert(
            "Thank you for choosing FoodieHub!\n" +
            food.name + " - ₹" + food.price
        );

    });

    bottom.append(price, orderButton);

    content.append(category, heading, description, bottom);

    card.append(imageWrap, content);

    // No automatic image search for Maharashtra and South Indian menus.

    return card;
}


// 10. DISPLAY FOOD MENU

function displayMenu(menuName) {

    if (!foodGrid) return;

    const selectedMenu = foodMenus[menuName];

    if (!selectedMenu) return;

    foodGrid.innerHTML = "";

    selectedMenu.forEach((food, index) => {

        foodGrid.appendChild(createFoodCard(food, index));

    });

    if (menuCount) {

        menuCount.textContent =
            selectedMenu.length + " Delicious Items";

    }
}


// 11. CHANGE CUISINE

function changeCuisine(cuisine) {

    if (!foodMenus[cuisine]) return;

    document.body.classList.remove(
        "theme-maharashtra",
        "theme-south"
    );

    document.body.classList.add(
        cuisine === "south"
            ? "theme-south"
            : "theme-maharashtra"
    );

    const buttons = document.querySelectorAll(".cuisine-card");

    buttons.forEach(button => {

        button.classList.toggle(
            "active",
            button.dataset.cuisine === cuisine
        );

    });

    if (menuTitle) {

        menuTitle.innerHTML =
            cuisine === "south"
                ? 'South Indian <span>Special</span>'
                : 'Authentic Maharashtra <span>Delights</span>';

    }

    if (menuDescription) {

        menuDescription.textContent =
            cuisine === "south"
                ? "Taste the traditional flavours of South India."
                : "Experience the rich culinary heritage of Maharashtra.";

    }

    displayMenu(cuisine);
}


// 12. CUISINE BUTTON EVENTS

document.querySelectorAll(".cuisine-card").forEach(button => {

    button.addEventListener("click", function () {

        changeCuisine(this.dataset.cuisine);

        const menuSection = document.getElementById("menu");

        if (menuSection) {

            menuSection.scrollIntoView({
                behavior: "smooth",
                block: "start"
            });

        }

    });

});


// 13. MOBILE NAVIGATION

const menuToggle = document.getElementById("menuToggle");
const navLinks = document.getElementById("navLinks");

if (menuToggle && navLinks) {

    menuToggle.addEventListener("click", function () {

        navLinks.classList.toggle("open");

        menuToggle.setAttribute(
            "aria-expanded",
            navLinks.classList.contains("open")
        );

    });

    navLinks.querySelectorAll("a").forEach(link => {

        link.addEventListener("click", function () {

            navLinks.classList.remove("open");
            menuToggle.setAttribute("aria-expanded", "false");

        });

    });

}

